package com.wealthflow;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import org.springframework.dao.DataIntegrityViolationException;import java.math.BigDecimal;import static org.assertj.core.api.Assertions.assertThat;import static org.assertj.core.api.Assertions.assertThatThrownBy;
@DataJpaTest class ChargebackJpaTest {@Autowired ChargebackRepository repo;@Test void persistsChargebackAndEnforcesUniqueEventId(){repo.saveAndFlush(new ChargebackRecord("cb-1","event-1",new BigDecimal("100.00")));assertThat(repo.findById("cb-1")).get().extracting(ChargebackRecord::getBilledTotal).isEqualTo(new BigDecimal("100.00"));repo.saveAndFlush(new ChargebackRecord("cb-2","event-2",new BigDecimal("1.00")));assertThatThrownBy(()->repo.saveAndFlush(new ChargebackRecord("cb-3","event-2",new BigDecimal("2.00")))).isInstanceOf(DataIntegrityViolationException.class);}}
